-- Meanings for the content words of the Reading practice passages, so that clicking a word in a passage shows what it
-- means. Each word gets one sense: the part of speech, the Vietnamese meaning and, as its example, the sentence of a
-- passage that holds it. A word that is already in the library keeps its row (the pronunciation rows of the dictation words
-- are INACTIVE and stay so, so the search and the catalogue do not change); a word that is not gets an INACTIVE row. The
-- lookup of a clicked word does not depend on the status of the word, only on the status of the sense.
-- The meanings are original text written for this project and still need a review.

CREATE TEMP TABLE reading_vocabulary (
    lemma TEXT NOT NULL,
    part_of_speech TEXT NOT NULL,
    vietnamese_meaning TEXT NOT NULL,
    example_sentence TEXT NOT NULL
) ON COMMIT DROP;


SELECT r.lemma, lower(r.lemma), 'INACTIVE'
FROM reading_vocabulary r
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_items i WHERE i.normalized_lemma = lower(r.lemma));

SELECT (SELECT i.id FROM vocabulary_items i WHERE i.normalized_lemma = lower(r.lemma) ORDER BY i.created_at LIMIT 1),
       r.part_of_speech, r.vietnamese_meaning, r.example_sentence, 0, 'ACTIVE'
FROM reading_vocabulary r
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_senses s JOIN vocabulary_items i ON i.id = s.vocabulary_item_id
                  WHERE i.normalized_lemma = lower(r.lemma));
